"""Private 2 Redis + 5 Sentinel processes; loopback and temporary paths only."""
import pathlib,tempfile,socket,subprocess,time
from redis_native import Client,RedisError

class SentinelLab:
 def __init__(self):self.processes={};self.clients={};self.ports={};self.used=set()
 def port(self):
  while True:
   with socket.socket() as endpoint:endpoint.bind(('127.0.0.1',0));value=endpoint.getsockname()[1]
   if value not in self.used:self.used.add(value);return value
 def __enter__(self):
  self.temp=tempfile.TemporaryDirectory(prefix='of-sentinel-');self.root=pathlib.Path(self.temp.name)
  try:
   for name in ['primary','replica']+['s'+str(i) for i in range(5)]:self.ports[name]=self.port()
   for name in ('primary','replica'):
    folder=self.root/name;folder.mkdir()
    text='bind 127.0.0.1\nprotected-mode yes\nport '+str(self.ports[name])+'\nunixsocket '+str(folder/'redis.sock')+'\nunixsocketperm 700\ndir '+str(folder)+'\nsave ""\nappendonly no\nrepl-diskless-sync-delay 0\nlogfile '+str(folder/'server.log')+'\n'
    if name=='replica':text+='replicaof 127.0.0.1 '+str(self.ports['primary'])+'\n'
    (folder/'config').write_text(text);self.start(name)
   self.wait(lambda:self.command('replica','INFO','replication').find('master_link_status:up')>=0,'replication link',12)
   self.command('primary','SET','fixture-data','preserved');assert self.command('primary','WAIT',1,2000)==1
   for i in range(5):
    name='s'+str(i);folder=self.root/name;folder.mkdir()
    text='bind 127.0.0.1\nprotected-mode yes\nport '+str(self.ports[name])+'\nunixsocket '+str(folder/'redis.sock')+'\nunixsocketperm 700\ndir '+str(folder)+'\nlogfile '+str(folder/'server.log')+'\nsentinel monitor primary 127.0.0.1 '+str(self.ports['primary'])+' 2\nsentinel down-after-milliseconds primary 350\nsentinel failover-timeout primary 2000\nsentinel parallel-syncs primary 1\nsentinel announce-ip 127.0.0.1\n'
    (folder/'config').write_text(text);self.start(name)
   self.wait(lambda:all(self.master(i).get('num-other-sentinels')=='4' and self.master(i).get('num-slaves')=='1' for i in range(5)),'five known voters and replica',18)
   self.wait(lambda:all(self.quorum(i) for i in range(5)),'initial majority',5)
   print('NATIVE_SENTINEL_FIVE_VOTERS_READY',flush=True);return self
  except BaseException:self.__exit__(None,None,None);raise
 def start(self,name):
  if name in self.processes and self.processes[name].poll() is None:return
  folder=self.root/name;args=['redis-server',str(folder/'config')]
  if name.startswith('s'):args.append('--sentinel')
  self.processes[name]=subprocess.Popen(args,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
  for _ in range(250):
   if self.processes[name].poll() is not None:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: '+name+' exited: '+(folder/'server.log').read_text(errors='replace')[-1500:])
   try:
    client=Client(folder/'redis.sock')
    if client.command('PING')=='PONG':self.clients[name]=client;return
    client.close()
   except (OSError,ConnectionError):pass
   time.sleep(.01)
  raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: private Redis readiness')
 def stop(self,name):
  if name in self.clients:self.clients.pop(name).close()
  process=self.processes.get(name)
  if process and process.poll() is None:
   process.terminate()
   try:process.wait(timeout=2)
   except subprocess.TimeoutExpired:process.kill();process.wait(timeout=2)
 def command(self,name,*args):
  try:return self.clients[name].command(*args)
  except (OSError,ConnectionError):
   # Promotion may disconnect normal clients; retry only a read-only observation.
   readonly=args[0] in ('PING','INFO','ROLE','GET') or args[0]=='SENTINEL' and args[1] in ('MASTER','CKQUORUM','GET-MASTER-ADDR-BY-NAME')
   if not readonly:raise
   self.clients.pop(name).close();self.clients[name]=Client(self.root/name/'redis.sock')
   return self.clients[name].command(*args)
 def master(self,i):
  raw=self.command('s'+str(i),'SENTINEL','MASTER','primary');return dict(zip(raw[::2],raw[1::2]))
 def quorum(self,i):
  try:return self.command('s'+str(i),'SENTINEL','CKQUORUM','primary').startswith('OK')
  except RedisError as error:
   if str(error).startswith('NOQUORUM'):return False
   raise
 def wait(self,predicate,description,seconds):
  deadline=time.monotonic()+seconds
  while time.monotonic()<deadline:
   if predicate():return
   time.sleep(.05)
  raise AssertionError('native Sentinel deadline: '+description)
 def __exit__(self,*args):
  for name in list(self.processes):self.stop(name)
  self.temp.cleanup()
